#!/usr/bin/env python3
"""reapply8 — the fixes that postdate reapply1-7 (lost again in reset #21):
  1. openai.ts  — live-verified OpenAI Responses API contract
     (json_object not json, lowercase-json input guard, per-model
      temperature auto-learning). Full-file write.
  2. test/openai-client.mjs — the 14/14 contract test (mocked fetch).
  3. server.ts  — startup reconcile: orphaned running/cancelling jobs →
     'interrupted' once at boot (crash-consistency).
  4. jobs.ts    — hydrateJob no longer stamps interrupted per-load
     (it misfired on fresh uploads).
Idempotent: full-file writes compare content; patches assert anchors.
"""
import os, sys

ROOT = '/home/user/Syntheniq'

def patch(path, old, new, tag):
    p = os.path.join(ROOT, path)
    s = open(p).read()
    if new in s:
        print(f'  = {tag} (already applied)')
        return
    if old not in s:
        print(f'  ! {tag} ANCHOR MISSING — inspect {path}')
        sys.exit(1)
    s = s.replace(old, new, 1)
    open(p, 'w').write(s)
    print(f'  + {tag}')

def write(path, content, tag):
    p = os.path.join(ROOT, path)
    os.makedirs(os.path.dirname(p), exist_ok=True)
    if os.path.exists(p) and open(p).read() == content:
        print(f'  = {tag} (unchanged)')
        return
    open(p, 'w').write(content)
    print(f'  + {tag} (written)')

write('apps/api/src/ai/openai.ts', "import { AiError, type LLMRequest, type LLMResult } from './types.js';\n\nconst BASE = 'https://api.openai.com/v1';\n\n/**\n * OpenAI \u2014 Responses API (current official API as of 2026-09).\n * POST /v1/responses with `instructions` + `input`.\n *\n * Live-verified contract (locked by test/openai-client.mjs, 2026-09-17):\n *  - structured output: `text.format = { type: \"json_object\" }` \u2014 the value\n *    \"json\" is REJECTED with 400; only json_object / text / json_schema work.\n *  - json_object requires the input to contain the lowercase word \"json\",\n *    otherwise the API 400s \u2192 we guard the input.\n *  - `temperature` is REJECTED (400) by some models (gpt-5.6-*) \u2192 per-model\n *    auto-learning: on a 400 mentioning temperature we remember the model\n *    and retry once without the field (never fail the job over it).\n */\nconst modelsRejectingTemperature = new Set<string>();\n\nexport function _resetTemperatureLearning(): void {\n  modelsRejectingTemperature.clear();\n}\n\nfunction buildBody(req: LLMRequest, model: string, withTemperature: boolean): Record<string, unknown> {\n  const content: Array<Record<string, unknown>> = [];\n  for (const img of req.images ?? []) {\n    content.push({\n      type: 'input_image',\n      image_url: `data:${img.mimeType};base64,${img.data}`,\n    });\n  }\n  let text = req.input;\n  if (req.json && !/json/i.test(text)) text += '\\nRespond in valid JSON.';\n  content.push({ type: 'input_text', text });\n\n  const body: Record<string, unknown> = {\n    model,\n    instructions: req.system,\n    input: [{ role: 'user', content }],\n    max_output_tokens: req.maxTokens ?? 8000,\n  };\n  if (withTemperature) body.temperature = req.temperature ?? 0.3;\n  if (req.json) body.text = { format: { type: 'json_object' } };\n  return body;\n}\n\nexport async function callOpenai(req: LLMRequest, apiKey: string, model: string): Promise<LLMResult> {\n  const t0 = Date.now();\n  const withTemperature = !modelsRejectingTemperature.has(model);\n\n  let res: Response;\n  try {\n    res = await fetch(`${BASE}/responses`, {\n      method: 'POST',\n      headers: { 'content-type': 'application/json', authorization: `Bearer ${apiKey}` },\n      body: JSON.stringify(buildBody(req, model, withTemperature)),\n    });\n  } catch (e) {\n    throw new AiError(`openai network error: ${(e as Error).message}`, true);\n  }\n\n  // temperature rejected by this model \u2192 learn it, retry once without the field\n  if (res.status === 400 && withTemperature) {\n    const errText = await res.text().catch(() => '');\n    if (/temperature/i.test(errText)) {\n      modelsRejectingTemperature.add(model);\n      res = await fetch(`${BASE}/responses`, {\n        method: 'POST',\n        headers: { 'content-type': 'application/json', authorization: `Bearer ${apiKey}` },\n        body: JSON.stringify(buildBody(req, model, false)),\n      });\n    } else {\n      throw new AiError(`openai ${model}: ${errText.slice(0, 300)}`, false, res.status);\n    }\n  }\n\n  const data: any = await res.json().catch(() => ({}));\n  if (!res.ok) {\n    const msg = data?.error?.message || `HTTP ${res.status}`;\n    const retryable = res.status === 429 || res.status >= 500 || res.status === 408;\n    throw new AiError(`openai ${model}: ${msg}`, retryable, res.status);\n  }\n\n  const text: string = typeof data.output_text === 'string' ? data.output_text : extractText(data);\n  return {\n    text,\n    json: req.json ? parseJson(text) : null,\n    provider: 'openai',\n    model,\n    latencyMs: Date.now() - t0,\n  };\n}\n\nfunction extractText(data: any): string {\n  const parts: string[] = [];\n  for (const item of data?.output ?? []) {\n    if (item.type === 'message') {\n      for (const c of item.content ?? []) if (c.type === 'output_text') parts.push(c.text);\n    }\n  }\n  return parts.join('\\n');\n}\n\nexport function parseJson(text: string): unknown {\n  const trimmed = text.trim();\n  try {\n    return JSON.parse(trimmed);\n  } catch {\n    // Strip code fences / trailing prose: find first { ... last }\n    const start = trimmed.indexOf('{');\n    const end = trimmed.lastIndexOf('}');\n    if (start >= 0 && end > start) {\n      try {\n        return JSON.parse(trimmed.slice(start, end + 1));\n      } catch {\n        /* fall through */\n      }\n    }\n    throw new Error('provider returned non-JSON text');\n  }\n}\n", 'openai.ts: live-verified API contract')
write('apps/api/test/openai-client.mjs', "#!/usr/bin/env node\n/**\n * openai-client \u2014 locks in the LIVE OpenAI Responses API contract\n * (verified against api.openai.com 2026-09-17). 14/14 must PASS.\n *\n *   1. posts to /v1/responses with the configured model\n *   2. json:true      \u2192 text.format.type = \"json_object\" (NOT \"json\" \u2014 400)\n *   3. json guard     \u2192 input lacking lowercase \"json\" gets \"Respond in valid JSON.\" appended\n *   4. json guard off \u2192 input already containing \"json\" is left untouched\n *   5. json:false     \u2192 no text.format field at all\n *   6. temperature    \u2192 sent by default for an unlearned model\n *   7. temp rejected  \u2192 400 mentioning temperature \u21d2 model learned, retried WITHOUT it, succeeds\n *   8. temp learned   \u2192 next call for same model sends no temperature from the start\n *   9. per-model      \u2192 learning is per-model: a different model still sends temperature\n *  10. other 400      \u2192 non-temperature 400 throws AiError (no silent retry)\n *  11. 429            \u2192 retryable AiError\n *  12. 500            \u2192 retryable AiError\n *  13. success text   \u2192 output_text returned, provider/model stamped\n *  14. success json   \u2192 fenced/loose JSON parsed via parseJson\n *  15. image data URL \u2192 input_image uses \"data:<mime>;base64,<b64>\" (live 400\n *                       \"without the ',' separator\" proves the comma is required)\n *\n * Mocks global fetch \u2014 no network, no key needed.\n */\nimport { callOpenai, _resetTemperatureLearning } from '../dist/ai/openai.js';\nimport { AiError } from '../dist/ai/types.js';\n\nlet pass = 0;\nlet fail = 0;\nfunction check(name, cond, detail = '') {\n  if (cond) {\n    pass++;\n    console.log(`  PASS  ${name}`);\n  } else {\n    fail++;\n    console.log(`  FAIL  ${name}${detail ? ` \u2014 ${detail}` : ''}`);\n  }\n}\n\n// fetch mock harness: queued responses (Response-like), captures request bodies\nlet captured = [];\nlet queued = [];\nlet realFetch = globalThis.fetch;\nglobalThis.fetch = async (url, opts) => {\n  const body = JSON.parse(opts.body);\n  captured.push({ url: String(url), body });\n  const next = queued.shift() ?? okResponse('{\"ok\": true}');\n  return next;\n};\n\nfunction okResponse(payload, { outputText } = {}) {\n  const data = {\n    output_text: outputText !== undefined ? outputText : String(payload),\n    output: [],\n  };\n  return {\n    ok: true,\n    status: 200,\n    json: async () => data,\n    text: async () => JSON.stringify(data),\n  };\n}\nfunction errResponse(status, message) {\n  const msg = message ?? 'error';\n  return {\n    ok: false,\n    status,\n    json: async () => ({ error: { message: msg } }),\n    text: async () => JSON.stringify({ error: { message: msg } }),\n  };\n}\n\nconst KEY = 'sk-test';\nconst MODEL = 'gpt-5.6-luna';\nconst req = (over = {}) => ({\n  task: 'plan',\n  system: 'You are an editor.',\n  input: over.input ?? 'Pick the moments.',\n  json: over.json ?? false,\n  temperature: over.temperature ?? 0.3,\n});\n\ntry {\n  // \u2500\u2500 1. endpoint + model \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  queued = [okResponse('{\"a\":1}')];\n  captured = [];\n  await callOpenai(req(), KEY, MODEL);\n  check(\n    'posts to /v1/responses with the configured model',\n    captured[0]?.url.endsWith('/v1/responses') && captured[0]?.body?.model === MODEL,\n    `${captured[0]?.url} ${captured[0]?.body?.model}`,\n  );\n\n  // \u2500\u2500 2. json_object format \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  queued = [okResponse('{\"a\":1}')];\n  captured = [];\n  await callOpenai(req({ json: true }), KEY, MODEL);\n  check(\n    'json:true \u2192 text.format.type = \"json_object\"',\n    captured[0]?.body?.text?.format?.type === 'json_object',\n    JSON.stringify(captured[0]?.body?.text),\n  );\n\n  // \u2500\u2500 3. lowercase-json input guard \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  queued = [okResponse('{\"a\":1}')];\n  captured = [];\n  await callOpenai(req({ json: true, input: 'Pick the moments.' }), KEY, MODEL);\n  const inputText =\n    captured[0]?.body?.input?.[0]?.content?.find((c) => c.type === 'input_text')?.text ?? '';\n  check(\n    'input lacking \"json\" gets JSON instruction appended',\n    /respond in valid json\\./i.test(inputText),\n    JSON.stringify(inputText),\n  );\n\n  // \u2500\u2500 4. guard does not double-add \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  queued = [okResponse('{\"a\":1}')];\n  captured = [];\n  await callOpenai(req({ json: true, input: 'Return JSON only.' }), KEY, MODEL);\n  const inputText2 =\n    captured[0]?.body?.input?.[0]?.content?.find((c) => c.type === 'input_text')?.text ?? '';\n  check(\n    'input already containing \"json\" left untouched',\n    inputText2 === 'Return JSON only.',\n    JSON.stringify(inputText2),\n  );\n\n  // \u2500\u2500 5. no format field when json:false \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  queued = [okResponse('{\"a\":1}')];\n  captured = [];\n  await callOpenai(req({ json: false }), KEY, MODEL);\n  check('json:false \u2192 no text.format', !('text' in (captured[0]?.body ?? {})));\n\n  // \u2500\u2500 6. temperature sent by default \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  _resetTemperatureLearning();\n  queued = [okResponse('{\"a\":1}')];\n  captured = [];\n  await callOpenai(req({ temperature: 0.3 }), KEY, 'gpt-5.6-luna');\n  check(\n    'temperature sent for unlearned model',\n    captured[0]?.body?.temperature === 0.3,\n    JSON.stringify(captured[0]?.body?.temperature),\n  );\n\n  // \u2500\u2500 7. temperature rejected \u2192 learn + retry without it \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  _resetTemperatureLearning();\n  queued = [\n    errResponse(400, \"Unsupported value: 'temperature' is not supported with this model.\"),\n    okResponse('{\"a\":2}'),\n  ];\n  captured = [];\n  const r7 = await callOpenai(req({ temperature: 0.3 }), KEY, MODEL);\n  check('temp 400 \u2192 retried without temperature, succeeds', captured.length === 2 && captured[1]?.body?.temperature === undefined && r7.text === '{\"a\":2}', `calls=${captured.length}`);\n\n  // \u2500\u2500 8. learned model skips temperature from the start \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  queued = [okResponse('{\"a\":3}')];\n  captured = [];\n  await callOpenai(req({ temperature: 0.3 }), KEY, MODEL);\n  check(\n    'learned model sends no temperature (single call)',\n    captured.length === 1 && captured[0]?.body?.temperature === undefined,\n  );\n\n  // \u2500\u2500 9. learning is per-model \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  queued = [okResponse('{\"a\":4}')];\n  captured = [];\n  await callOpenai(req({ temperature: 0.2 }), KEY, 'gpt-5.6-terra');\n  check(\n    'different model still sends temperature',\n    captured[0]?.body?.temperature === 0.2,\n    JSON.stringify(captured[0]?.body?.temperature),\n  );\n\n  // \u2500\u2500 10. non-temperature 400 throws (no silent retry) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  _resetTemperatureLearning();\n  queued = [errResponse(400, \"Invalid value for 'max_output_tokens'\")];\n  captured = [];\n  let threw10 = null;\n  try {\n    await callOpenai(req(), KEY, 'gpt-5.6-luna');\n  } catch (e) {\n    threw10 = e;\n  }\n  check(\n    'other 400 \u2192 AiError, exactly one call',\n    threw10 instanceof AiError && captured.length === 1,\n    `${threw10?.message} calls=${captured.length}`,\n  );\n\n  // \u2500\u2500 11. 429 retryable \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  queued = [errResponse(429, 'Rate limited')];\n  let err11 = null;\n  try {\n    await callOpenai(req(), KEY, MODEL);\n  } catch (e) {\n    err11 = e;\n  }\n  check('429 \u2192 retryable AiError', err11 instanceof AiError && err11.retryable === true, String(err11?.retryable));\n\n  // \u2500\u2500 12. 500 retryable \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  queued = [errResponse(500, 'boom')];\n  let err12 = null;\n  try {\n    await callOpenai(req(), KEY, MODEL);\n  } catch (e) {\n    err12 = e;\n  }\n  check('500 \u2192 retryable AiError', err12 instanceof AiError && err12.retryable === true, String(err12?.retryable));\n\n  // \u2500\u2500 13. success: output_text + stamps \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  queued = [okResponse('{\"x\":1}', { outputText: 'hello there' })];\n  const r13 = await callOpenai(req(), KEY, MODEL);\n  check(\n    'success \u2192 output_text, provider/model stamped',\n    r13.text === 'hello there' && r13.provider === 'openai' && r13.model === MODEL && r13.latencyMs >= 0,\n    JSON.stringify({ t: r13.text, p: r13.provider }),\n  );\n\n  // \u2500\u2500 14. success: fenced JSON parsed \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  queued = [okResponse('{\"y\":2}', { outputText: '```json\\n{\"clip\": 1}\\n```' })];\n  const r14 = await callOpenai(req({ json: true }), KEY, MODEL);\n  check('success json \u2192 fenced payload parsed', r14.json?.clip === 1, JSON.stringify(r14.json));\n\n  // \u2500\u2500 15. image data URL has the comma separator \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  queued = [okResponse('{\"z\":6}')];\n  captured = [];\n  await callOpenai(\n    { ...req(), images: [{ data: 'QUJD', mimeType: 'image/jpeg' }] },\n    KEY,\n    MODEL,\n  );\n  const imgUrl =\n    captured[0]?.body?.input?.[0]?.content?.find((c) => c.type === 'input_image')?.image_url ?? '';\n  check(\n    'image \u2192 data URL with comma separator',\n    imgUrl === 'data:image/jpeg;base64,QUJD',\n    imgUrl,\n  );\n} finally {\n  globalThis.fetch = realFetch;\n}\n\nconsole.log(`\\nopenai-client: ${pass}/15 pass, ${fail} fail`);\nprocess.exit(fail === 0 ? 0 : 1);\n", 'test/openai-client.mjs (14/14 contract test)')
patch('apps/api/src/server.ts', "app.listen({ port: PORT, host: '0.0.0.0' });", "// \u2500\u2500 startup reconcile (crash-consistency) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// If the server died mid-job, its persisted state still says\n// running/cancelling. Mark those orphans 'interrupted' ONCE at boot so the\n// UI shows \"Paused \u2014 resume ready\" and POST /retry can resume from the last\n// completed stage (intermediate artifacts are persisted on disk). This must\n// happen at startup only \u2014 NOT inside hydrateJob (that misfired on fresh\n// uploads whose job legitimately starts running).\n{\n  const orphans = await listProjects();\n  for (const summary of orphans) {\n    const state = await loadJob(summary.id);\n    if (state && (state.status === 'running' || state.status === 'cancelling')) {\n      const orphaned = state.status;\n      state.status = 'interrupted';\n      state.error = 'interrupted by server restart \u2014 retry resumes from the last completed stage';\n      await saveJob(state);\n      app.log.info(`startup: ${state.id} marked interrupted (orphaned ${orphaned})`);\n    }\n  }\n}\n\n" + "app.listen({ port: PORT, host: '0.0.0.0' });", 'server.ts: startup reconcile')
patch('apps/api/src/jobs.ts', "  // Resume guard: a job left \"running\" by a crash can RESUME from the last\n  // completed stage (intermediate artifacts are persisted on disk).\n  if (state.status === 'running' || state.status === 'cancelling') {\n    state.status = 'interrupted';\n    state.error = 'interrupted by server restart \u2014 retry resumes from the last completed stage';\n  }\n", "  // NOTE: crash handling for jobs left 'running' by a dead server is\n  // centralized in server.ts startup reconcile. No per-load stamping here \u2014\n  // it misfired on fresh uploads whose job legitimately starts running.\n", 'jobs.ts: hydrateJob guard removed')
print('reapply8: OK')
